(function () {
    const pending = {};
    let reqCounter = 1;

    window.addEventListener('message', function (event) {
        const msg = event.data;
        if (!msg || typeof msg !== 'object') return;

        const payload = msg.data || {};
        const reqId = payload.request_id || msg.request_id;
        if (reqId && pending[reqId]) {
            const { resolve, reject } = pending[reqId];
            delete pending[reqId];
            if (msg.type && msg.type.endsWith('Failed')) {
                reject(payload);
            } else {
                resolve(payload);
            }
        }
    });

    window.vkBridge = {
        send: function (method, params) {
            return new Promise(function (resolve, reject) {
                const requestId = 'req_' + (reqCounter++);
                const data = Object.assign({}, params || {}, { request_id: requestId });
                pending[requestId] = { resolve, reject };

                const message = {
                    handler: method,
                    params: data,
                    type: 'vk-connect',
                    webFrameId: window.name || ''
                };

                if (window.parent && window.parent !== window) {
                    window.parent.postMessage(message, '*');
                } else {
                    delete pending[requestId];
                    resolve({ result: true });
                }

                setTimeout(function () {
                    if (pending[requestId]) {
                        delete pending[requestId];
                        resolve({ result: true });
                    }
                }, 4000);
            });
        },
        supports: function () {
            return true;
        }
    };
})();
